use quantion::{
    CalculateEicOptions, FindPeaksOptions, FindTargetsOptions, ParseIonOptions, QuantionError, Target, find_targets,
    parse_ion,
};

fn main() -> Result<(), QuantionError> {
    let ids = ["compound_1", "compound_2", "compound_3"];
    let targets = vec![
        Target { id: Some(ids[0].to_string()), mz: 260.1034, rt: 2.383, range: Some(0.05) },
        Target { id: Some(ids[1].to_string()), mz: 317.1250, rt: 1.903, range: Some(0.05) },
        Target { id: Some(ids[2].to_string()), mz: 188.0818, rt: 3.060, range: Some(0.05) },
    ];

    let mut file = parse_ion("https://raw.githubusercontent.com/phenological/ion-files/main/data/aa_p21_LTR_20_b1_w20.ion", ParseIonOptions::default())?;
    let options = FindTargetsOptions {
        eic: CalculateEicOptions { from: 1.5, to: 3.5, ..Default::default() },
        find_peaks: FindPeaksOptions { min_intensity: 1000.0, ..Default::default() },
        threads: 4,
    };
    let peaks = find_targets(&mut file, &targets, options)?;

    for index in 0..peaks.len() {
        let peak = &peaks[index];
        println!("{}: rt {:.3}  intensity {:.0}  integral {:.0}", ids[index], peak.rt, peak.intensity, peak.integral);
    }
    Ok(())
}

