use quantion::{CalculateEicOptions, FindFeaturesOptions, GridOptions, ParseIonOptions, QuantionError, find_features, parse_ion};

fn main() -> Result<(), QuantionError> {
    let mut file = parse_ion("https://raw.githubusercontent.com/phenological/ion-files/main/data/aa_p21_LTR_20_b1_w20.ion", ParseIonOptions::default())?;
    let options = FindFeaturesOptions {
        eic: CalculateEicOptions { from: 2.3, to: 2.45, ..Default::default() },
        grid: GridOptions { start: 255.0, end: 265.0, ..Default::default() },
        threads: 2,
        ..Default::default()
    };
    let features = find_features(&mut file, options)?;

    println!("{} features", features.len());
    let mut count = 3;
    if features.len() < count {
        count = features.len();
    }
    for index in 0..count {
        let feature = &features[index];
        println!("m/z {:.4}  rt {:.3}  intensity {:.0}", feature.mz, feature.rt, feature.intensity);
    }
    Ok(())
}

